	print("\n=== STEP 1: RAW GLB WHEELS AND NODES ===")
	var glb_path = "res://assets/models/cars/kia_seltos/source/Mexico_Seltos_PE_pc13.glb"
	var glb_res = load(glb_path) as PackedScene
	var root = glb_res.instantiate()

	for child in root.find_children("*", "Node3D", true, false):
		var n = child.name.to_lower()
