				print("  Body Child: %s, pos: %s, rot_deg: %s" % [bc.name, str(bc.position), str(bc.rotation_degrees)])

	print("\n=== STEP 3: WHERE ARE TIRES IN car_kia_seltos.tscn COORDINATE SPACE? ===")
	# If car is placed at origin with identity transform:
	for child in car.find_children("*", "Node3D", true, false):
		var n = child.name.to_lower()
		if "tire" in n:
			var car_local = car.to_local(child.global_position)
