"@tool
extends SceneTree

func _init() -> void:
	print("=== REPRODUCING SELTOS BUG ===")
	var car = VehiclePhysicsCore.new()
	var config = VehicleRegistry.get_config("kia_seltos")
	root.add_child(car)
	car.initialize_vehicle(config)

	print("Config display_name: ", config.display_name)
	print("Car initial position: ", car.position)
	print("Car forward vector (-basis.z): ", -car.global_transform.basis.z)

	# Simulate pressing W (throttle = 1.0) for 1 second (60 physics steps)
	car.set_driver_input(1.0, 0.0, 0.0, 0.0)
	for i in range(60):
		car._physics_process(1.0 / 60.0)

	print("After 1s W (throttle):")
	print("  Linear velocity: ", car.linear_velocity)
	print("  Forward speed: ", car.forward_speed)
	print("  Position: ", car.global_position)

	# Check where visual bonnet is in world space
	if car.visual_adapter and car.visual_adapter.visual_instance:
		var bonet = car.visual_adapter.visual_instance.find_child("00_010 bonet", true, false)
		if bonet:
			print("  Bonnet world position: ", bonet.global_position)
		var grille = car.visual_adapter.visual_instance.find_child("00_128 GRILLE-RADIATOR", true, false)
		if grille:
			print("  Grille world position: ", grille.global_position)

	car.queue_free()
	quit(0)
