"@tool
extends SceneTree

func _init() -> void:
	var ref_img = Image.load_from_file("res://docs/validation/reference_1080p.png")
	var cur_img = Image.load_from_file("res://docs/validation/current_homescreen.png")
	if not ref_img or not cur_img:
		print("Error loading images")
		quit(1)
		return

	var w = min(ref_img.get_width(), cur_img.get_width())
	var h = min(ref_img.get_height(), cur_img.get_height())
	print("Comparing images of size %dx%d" % [w, h])

	# Key regions to check:
	var regions = {
		"ProfileCard": Rect2i(30, 20, 520, 180),
		"TopNavBar": Rect2i(580, 20, 750, 80),
		"CurrencyAndGear": Rect2i(1340, 20, 560, 130),
		"LimitedTimeEvent": Rect2i(1520, 200, 380, 330),
		"OnlineFriends": Rect2i(1520, 550, 380, 320),
		"PlayBtn": Rect2i(40, 260, 520, 120),
		"NavButtons": Rect2i(40, 380, 480, 400),
		"DailyMissionsAndMail": Rect2i(20, 920, 480, 140),
		"NewsBanner": Rect2i(590, 920, 760, 140),
		"SeasonPass": Rect2i(1500, 920, 400, 140)
	}

	for name in regions:
		var r = regions[name]
		var total_diff = 0.0
		var count = 0
		for y in range(r.position.y, r.position.y + r.size.y):
			for x in range(r.position.x, r.position.x + r.size.x):
				if x < w and y < h:
					var c1 = ref_img.get_pixel(x, y)
					var c2 = cur_img.get_pixel(x, y)
					var d = (abs(c1.r - c2.r) + abs(c1.g - c2.g) + abs(c1.b - c2.b)) / 3.0
					total_diff += d
					count += 1
		var avg_diff = total_diff / float(count) if count > 0 else 0.0
		print("Region '%s': Average diff = %.4f (%.2f%%)" % [name, avg_diff, avg_diff * 100.0])

	quit(0)
