"@tool
extends SceneTree

func _init():
	var ref = Image.load_from_file("docs/validation/reference_1080p.png")

	# Scan row y=40, 50, 60 for the entire top nav bar
	var bar_x = []
	for x in range(550, 1400):
		var c = ref.get_pixel(x, 50)
		# Bar has either orange tab, dark background, or white text
		# Outside bar is building/sky
		# In reference, bar background is dark gray/black (0.05 < c < 0.25) or orange (r>0.8, g>0.4)
		if (c.r > 0.8 and c.g > 0.4 and c.b < 0.25) or (c.r < 0.25 and c.g < 0.25 and c.b < 0.25):
			bar_x.append(x)
	# Also find rightmost tab text 'COMMUNITY'
	var comm_x = []
	for y in range(40, 75):
		for x in range(1150, 1350):
			var c = ref.get_pixel(x, y)
			if c.r > 0.8 and c.g > 0.8 and c.b > 0.8: # white text in COMMUNITY
				comm_x.append(x)
	if comm_x.size() > 0:
		print("COMMUNITY text X in ref: %d to %d" % [comm_x[0], comm_x[-1]])

	# Find orange HOME tab in ref
	var home_x = []
	for y in range(40, 75):
		for x in range(580, 750):
			var c = ref.get_pixel(x, y)
			if c.r > 0.85 and c.g > 0.4 and c.b < 0.25:
				home_x.append(x)
	if home_x.size() > 0:
		print("HOME orange tab X in ref: %d to %d (width %d)" % [home_x[0], home_x[-1], home_x[-1] - home_x[0]])

	# Currency pill in ref:
	var cur_x = []
	for y in range(40, 80):
		for x in range(1320, 1820):
			var c = ref.get_pixel(x, y)
			# Find dark background or gold coin or blue gem
			if (c.r > 0.8 and c.g > 0.7 and c.b < 0.2) or (c.b > 0.8 and c.r < 0.3):
				cur_x.append(x)
	if cur_x.size() > 0:
		print("Currency pill elements X in ref: %d to %d" % [cur_x[0], cur_x[-1]])

	quit(0)
"

