"@tool
extends SceneTree

func _init():
	var gltf = GLTFDocument.new()
	var state = GLTFState.new()
	var err = gltf.append_from_file("res://assets/models/cars/mclaren_650s_gt3/source/mclaren_650s_gt3.glb", state)
	if err != OK:
		print("ERROR appending GLTF: ", err)
		quit(1)
		return
	var scene = gltf.generate_scene(state)
	if not scene:
		print("ERROR generating scene from GLTF")
		quit(1)
		return

	print("--- ROOT NODE: ", scene.name, " ---")
	var mesh_count = 0
	var materials = {}

	var aabb = AABB()
	var first_aabb = true

	var stack = [scene]
	while not stack.is_empty():
		var node = stack.pop_back()
		if node is MeshInstance3D:
			mesh_count += 1
			if first_aabb:
				aabb = node.global_transform * node.get_aabb()
				first_aabb = false
			else:
				aabb = aabb.merge(node.global_transform * node.get_aabb())

			for s in range(node.get_surface_override_material_count()):
				var mat = node.get_surface_override_material(s)
				if mat:
					materials[mat.resource_name] = mat
			if node.mesh:
				for s in range(node.mesh.get_surface_count()):
					var mat = node.mesh.get_surface_material(s)
					if mat:
						materials[mat.resource_name] = mat
		for child in node.get_children():
			stack.push_back(child)

	print("Total Mesh Instances: ", mesh_count)
	print("Bounding Box Size: ", aabb.size, " Position: ", aabb.position)
	print("Total Unique Materials: ", materials.size())
	for mat_name in materials.keys():
		print("  - Material: ", mat_name)

	# Check children of root
	print("\n--- Direct Children of Scene ---")
	for child in scene.get_children():
		print("  ", child.name, " (", child.get_class(), ")")
		for subchild in child.get_children():
			print("    -> ", subchild.name, " (", subchild.get_class(), ")")

	quit(0)
