	print("--- All Materials in McLaren GLB ---")
	var mat_dict = {}
	for child in scene.get_children():
		if child is MeshInstance3D and child.mesh:
			for s in range(child.mesh.get_surface_count()):
				var mat = child.mesh.surface_get_material(s)
				if mat and not mat_dict.has(mat.resource_name):
					mat_dict[mat.resource_name] = {
						"mat": mat,
						"used_by": [child.name]
					}
				elif mat:
					mat_dict[mat.resource_name]["used_by"].append(child.name)

	for m_name in mat_dict.keys():
		var info = mat_dict[m_name]
		var mat = info["mat"] as StandardMaterial3D
		var alb = "null"
		if mat.albedo_texture:
			alb = "has_tex(%dx%d)" % [mat.albedo_texture.get_width(), mat.albedo_texture.get_height()]
		var nrm = "null"
		if mat.normal_texture:
			nrm = "has_tex(%dx%d)" % [mat.normal_texture.get_width(), mat.normal_texture.get_height()]
		print("Material '%s' (users: %s): albedo=%s normal=%s color=%s rough=%.2f metal=%.2f" % [
			m_name, str(info["used_by"]), alb, nrm, str(mat.albedo_color), mat.roughness, mat.metallic
		])
	quit(0)
