func _init():
	var gltf = GLTFDocument.new()
	var state = GLTFState.new()
	gltf.append_from_file("res://assets/models/cars/mclaren_650s_gt3/source/mclaren_650s_gt3.glb", state)
	var scene = gltf.generate_scene(state)

	var rim_mesh = scene.get_node_or_null("Mesh_12") as MeshInstance3D
	var arr = rim_mesh.mesh.surface_get_arrays(0)
	var verts = arr[Mesh.ARRAY_VERTEX] as PackedVector3Array

	# Cluster vertices into 4 quadrants: FL (X>0, Z>0), FR (X<0, Z>0), RL (X>0, Z<0), RR (X<0, Z<0)
	var fl = []
	var fr = []
	var rl = []
	var rr = []
	for v in verts:
		if v.z > 0: # Front
			if v.x < 0:
				fr.append(v)
			else:
				fl.append(v)
		else: # Rear
			if v.x < 0:
				rr.append(v)
			else:
				rl.append(v)

	func_calc_box("FL (Left Front)", fl)
	func_calc_box("FR (Right Front)", fr)
	func_calc_box("RL (Left Rear)", rl)
	func_calc_box("RR (Right Rear)", rr)
	quit(0)

func func_calc_box(name: String, pts: Array):
	if pts.is_empty():
		return
	var b = AABB(pts[0], Vector3.ZERO)
	for p in pts:
		b = b.expand(p)
	print("%s: center=%s size=%s count=%d" % [name, b.get_center(), b.size, pts.size()])
"

